from langgraph.func import entrypoint, task

@task
def add_one(value: int) -> int:
    return value + 1

@entrypoint()
def add_all(values: list[int]) -> list[int]:
    futures = [add_one(value) for value in values]
    return [future.result() for future in futures]

print(add_all.invoke([1, 2, 3]))

